ALTER TABLE public.gyms ADD COLUMN frozen_at timestamp with time zone, ADD COLUMN freeze_note text NOT NULL DEFAULT '';
ALTER TABLE public.owner_requests ADD COLUMN trial_started_at timestamp with time zone;

CREATE OR REPLACE FUNCTION public.gym_access(g uuid, area text DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.otp_verified() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND gym_id=g AND (area IS NULL OR role='Owner' OR (role!='Client' AND area=ANY(permissions)))) AND NOT EXISTS(SELECT 1 FROM public.gyms WHERE id=g AND frozen_at IS NOT NULL) $$;

CREATE OR REPLACE FUNCTION public.decide_owner_request(request_id uuid, approve boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.owner_requests; g uuid; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT * INTO r FROM public.owner_requests WHERE id=request_id FOR UPDATE; IF r.id IS NULL OR r.status NOT IN ('Pending','Rejected') THEN RAISE EXCEPTION 'Request unavailable'; END IF; IF approve THEN IF r.gym_id IS NOT NULL THEN g=r.gym_id; ELSE INSERT INTO public.gyms(name,owner_id) VALUES(r.gym_name,r.user_id) RETURNING id INTO g; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=r.user_id AND gym_id=g AND role='Owner') THEN INSERT INTO public.user_roles(user_id,gym_id,role,permissions) VALUES(r.user_id,g,'Owner',ARRAY['Members','Attendance','Sessions','Payments','Finance','Workout programs','Settings']); END IF; END IF; UPDATE public.owner_requests SET status=CASE WHEN approve THEN 'Approved' ELSE 'Rejected' END,decision_by=auth.uid(),decided_at=now(),gym_id=g WHERE id=r.id; RETURN g; END $$;
REVOKE ALL ON FUNCTION public.decide_owner_request(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.decide_owner_request(uuid,boolean) TO authenticated;

CREATE FUNCTION public.set_gym_frozen(g uuid, frozen boolean, note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; UPDATE public.gyms SET frozen_at=CASE WHEN frozen THEN now() ELSE NULL END, freeze_note=CASE WHEN frozen THEN left(coalesce(note,''),1000) ELSE '' END WHERE id=g; IF NOT FOUND THEN RAISE EXCEPTION 'Gym not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_gym_frozen(uuid,boolean,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_gym_frozen(uuid,boolean,text) TO authenticated;

CREATE FUNCTION public.owner_gate_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.owner_requests; g public.gyms; BEGIN SELECT * INTO g FROM public.gyms WHERE owner_id=auth.uid() ORDER BY created_at LIMIT 1; SELECT * INTO r FROM public.owner_requests WHERE user_id=auth.uid() ORDER BY created_at DESC LIMIT 1; RETURN jsonb_build_object('gymId',g.id,'frozen',coalesce(g.frozen_at IS NOT NULL,false),'freezeNote',coalesce(g.freeze_note,''),'requestStatus',r.status,'plan',r.plan,'gymName',coalesce(g.name,r.gym_name),'trialStartedAt',r.trial_started_at,'trialEndsAt',r.trial_started_at+interval '1 hour','now',now()); END $$;
REVOKE ALL ON FUNCTION public.owner_gate_state() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.owner_gate_state() TO authenticated;

CREATE FUNCTION public.start_owner_trial() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.owner_requests SET trial_started_at=now() WHERE user_id=auth.uid() AND status='Pending' AND trial_started_at IS NULL; RETURN public.owner_gate_state(); END $$;
REVOKE ALL ON FUNCTION public.start_owner_trial() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.start_owner_trial() TO authenticated;